for(var s=0;s<DATA.maxSteps;s++){
  var tool=DATA.tools[s%DATA.tools.length];
  console.log(' step '+(s+1)+' THOUGHT: need '+tool.purpose);
  console.log(' step '+(s+1)+' ACTION: '+tool.name+'('+JSON.stringify(tool.args)+')');
  obs=tool.result;
  console.log(' step '+(s+1)+' OBSERVATION: '+obs);
